// Runtime support for vecDSL programs generated for Pinecone with {{sdk.typescript.package}}. Generated by vecDSL 7. Do not edit.

import { Errors, Pinecone } from "{{sdk.typescript.package}}";
import type { Documents, FetchAPI } from "{{sdk.typescript.package}}";

const API_VERSION = "{{api.version}}";
const DEFAULT_NAMESPACE = "{{namespace}}";
const DEFAULT_CLOUD = "{{deployment.cloud}}";
const DEFAULT_REGION = "{{deployment.region}}";
const PAGE = 1000;
const LIST_PAGE = 100;
const BATCH = 100;
const SETTLE = 50;
const DIGITS = 6;
const MAX_ID = 512;
const RETRIES = 3;
const RETRIED = new Set([429, 500, 502, 503, 504]);
const EMBEDDED_BATCH = 96;
const OPERATORS = new Set(["and", "or", "not"]);

type Args = Record<string, any>;
type Layout = {
  name: string;
  namespace: string;
  key: string;
  key_type: "int" | "text";
  probe?: { type: string; field: string; dim?: number };
  limits?: Record<string, { dim?: number; max_items?: number; max_length?: number }>;
  defaults?: Args;
  max_batch?: number;
};
type Filter = Args;
type Match = Args & { _id: string; _score: number | null };
type Scored = { match: Match; score: number };
type Sparse = { indices: number[]; values: number[] };
type Vector = number[] | Sparse;
type Rewrite = { type: string; boosts?: Record<string, string>; fuzzy?: string; slop?: number; required?: boolean };
type Rerank = { model: string; query: string; field: string; top_n?: number; parameters?: Args };

export class UnsupportedFeature extends Error {}

/** A Pinecone REST response with a status other than 2xx. */
export class PineconeError extends Error {
  constructor(
    readonly status: number,
    message: string,
  ) {
    super(message);
  }
}

export function unsupported(vendor: string, feature: string): never {
  throw new UnsupportedFeature(`${feature} is not supported for target ${vendor}`);
}

export function env(name: string): string {
  const value = process.env[name];
  if (value === undefined) {
    throw new Error(`environment variable ${name} is not set`);
  }
  return value;
}

function seconds(name: string, fallback: number): number {
  return Number(process.env[name] ?? fallback);
}

/** The Pinecone client, the data-plane handles of the indexes a program uses, the last response's log positions and what REST calls need. */
export class Client {
  private readonly handles = new Map<string, Documents>();
  readonly hosts = new Map<string, string>();
  readonly schemas = new Map<string, Set<string>>();
  committed: number | undefined;
  reconciled: number | undefined;

  constructor(
    readonly pinecone: Pinecone,
    readonly indexHost: string | undefined,
    readonly control: string,
    readonly apiKey: string,
    readonly timeout: number,
  ) {}

  documents(layout: Layout): Documents {
    const handle = `${layout.name}/${layout.namespace}`;
    let found = this.handles.get(handle);
    if (found === undefined) {
      const target = this.indexHost ? { host: this.indexHost } : { name: layout.name };
      found = this.pinecone.index({ ...target, namespace: layout.namespace }).documents;
      this.handles.set(handle, found);
    }
    return found;
  }

  forget(name: string): void {
    this.hosts.delete(name);
    this.schemas.delete(name);
    for (const handle of [...this.handles.keys()]) {
      if (handle.startsWith(`${name}/`)) {
        this.handles.delete(handle);
      }
    }
  }

  async close(): Promise<void> {
    this.handles.clear();
  }
}

function position(headers: Headers, ...names: string[]): number | undefined {
  for (const name of names) {
    const value = headers.get(name);
    if (value !== null && /^\d+$/.test(value.trim())) {
      return Number(value.trim());
    }
  }
  return undefined;
}

export async function connect(args: { uri: string; api_key: string; index_host?: string; timeout?: number }): Promise<Client> {
  let client: Client | undefined;
  const recording: FetchAPI = async (input, init) => {
    const limit = args.timeout === undefined ? undefined : AbortSignal.timeout(args.timeout * 1000);
    const signal = limit === undefined ? init?.signal : init?.signal ? AbortSignal.any([init.signal, limit]) : limit;
    const response = await fetch(input, { ...init, signal });
    if (client !== undefined) {
      client.committed = position(response.headers, "x-pinecone-request-lsn", "x-pinecone-lsn-committed");
      client.reconciled = position(response.headers, "x-pinecone-max-indexed-lsn", "x-pinecone-lsn-reconciled");
    }
    return response;
  };
  const pinecone = new Pinecone({ apiKey: args.api_key, controllerHostUrl: args.uri, fetchApi: recording });
  client = new Client(pinecone, args.index_host || undefined, args.uri.replace(/\/+$/, ""), args.api_key, args.timeout ?? 30);
  return client;
}

/**
 * One REST request of API {{api.version}}; 429 and 5xx are retried three times with backoff from 0.5 s, and so is a dropped connection when the
 * request can be repeated (reads, deletes and document writes).
 */
async function send(client: Client, method: string, url: string, body?: unknown): Promise<any> {
  const headers: Record<string, string> = { "Api-Key": client.apiKey, "X-Pinecone-Api-Version": API_VERSION, Accept: "application/json" };
  if (body !== undefined) {
    headers["Content-Type"] = "application/json";
  }
  const repeatable = method !== "POST" || url.includes("/documents/");
  for (let attempt = 0; ; attempt++) {
    let response: Response;
    let text: string;
    try {
      response = await fetch(url, {
        method,
        headers,
        body: body === undefined ? undefined : JSON.stringify(body),
        signal: AbortSignal.timeout(client.timeout * 1000),
      });
      text = await response.text();
    } catch (error) {
      if (repeatable && attempt < RETRIES) {
        await new Promise((resolve) => setTimeout(resolve, 500 * 2 ** attempt));
        continue;
      }
      throw error;
    }
    if (RETRIED.has(response.status) && attempt < RETRIES) {
      await new Promise((resolve) => setTimeout(resolve, 500 * 2 ** attempt));
      continue;
    }
    if (!response.ok) {
      throw new PineconeError(response.status, `${method} ${url} returned ${response.status}: ${text}`);
    }
    client.committed = position(response.headers, "x-pinecone-request-lsn", "x-pinecone-lsn-committed");
    client.reconciled = position(response.headers, "x-pinecone-max-indexed-lsn", "x-pinecone-lsn-reconciled");
    return text.trim() === "" ? null : JSON.parse(text);
  }
}

function segment(name: string): string {
  return encodeURIComponent(name);
}

function control(client: Client, method: string, path: string, body?: unknown): Promise<any> {
  return send(client, method, client.control + path, body);
}

async function host(client: Client, name: string): Promise<string> {
  let found = client.indexHost ?? client.hosts.get(name);
  if (found === undefined) {
    found = (await control(client, "GET", `/indexes/${segment(name)}`)).host as string;
    client.hosts.set(name, found);
  }
  return found.includes("://") ? found.replace(/\/+$/, "") : `https://${found}`;
}

async function data(client: Client, name: string, method: string, path: string, body?: unknown): Promise<any> {
  return send(client, method, (await host(client, name)) + path, body);
}

function query(parameters: Record<string, string | number | undefined>): string {
  const present = Object.entries(parameters).filter(([, item]) => item !== undefined) as [string, string | number][];
  return present.length === 0 ? "" : "?" + new URLSearchParams(present.map(([key, item]): [string, string] => [key, String(item)])).toString();
}

/** Every item of a paginated listing; a repeated token ends the listing. */
async function paged(fetchPage: (token: string | undefined) => Promise<any>, items: string): Promise<any[]> {
  const found: any[] = [];
  const seen = new Set<string>();
  let token: string | undefined;
  for (;;) {
    const page = (await fetchPage(token)) ?? {};
    found.push(...(page[items] ?? []));
    const following: string | undefined = page.pagination?.next;
    if (!following || seen.has(following)) {
      return found;
    }
    seen.add(following);
    token = following;
  }
}

/** Polls every second until done() holds, for at most limit seconds; a limit of 0 skips the wait (API mock). */
async function poll(done: () => Promise<boolean>, what: string, limit: number): Promise<void> {
  if (limit <= 0) {
    return;
  }
  const deadline = Date.now() + limit * 1000;
  while (!(await done())) {
    if (Date.now() > deadline) {
      throw new Error(`${what} after ${limit} s`);
    }
    await new Promise((resolve) => setTimeout(resolve, 1000));
  }
}

/** Pinecone document id of a primary key: the decimal text of an integer, or the text itself. */
export function documentId(key: unknown): string {
  let text: string;
  if (typeof key === "number") {
    if (!Number.isInteger(key)) {
      throw new TypeError(`cannot use ${key} as a Pinecone primary key`);
    }
    text = BigInt(key).toString();
  } else if (typeof key === "bigint" || typeof key === "string") {
    text = String(key);
  } else {
    throw new TypeError(`cannot use ${String(key)} as a Pinecone primary key`);
  }
  if (text.length === 0 || text.length > MAX_ID || [...text].some((c) => c.charCodeAt(0) === 0 || c.charCodeAt(0) > 127)) {
    throw new RangeError(`Pinecone document ids are 1 to ${MAX_ID} ASCII characters: ${JSON.stringify(text)}`);
  }
  return text;
}

function keyOf(layout: Layout, id: string): number | string {
  if (layout.key_type !== "int") {
    return id;
  }
  if (!/^-?\d+$/.test(id)) {
    throw new RangeError(`document id ${id} is not an integer key`);
  }
  return Number(id);
}

/** Ids in key order; every id is checked against the key type first, as the other runtimes do. */
function sortIds(layout: Layout, ids: string[]): string[] {
  ids.forEach((id) => keyOf(layout, id));
  return ids.sort(compareIds(layout));
}

function compareIds(layout: Layout): (a: string, b: string) => number {
  if (layout.key_type === "int") {
    return (a, b) => {
      const difference = BigInt(a) - BigInt(b);
      return difference < 0n ? -1 : difference > 0n ? 1 : 0;
    };
  }
  return (a, b) => (a < b ? -1 : a > b ? 1 : 0);
}

/** Result values in one form for every host language: floats rounded, integral floats as integers. */
function value(item: unknown): unknown {
  if (typeof item === "number") {
    return Number.isFinite(item) ? Number(item.toFixed(DIGITS)) + 0 : item;
  }
  if (Array.isArray(item)) {
    return item.map(value);
  }
  if (item !== null && typeof item === "object") {
    return Object.fromEntries(Object.entries(item).map(([key, entry]) => [key, value(entry)]));
  }
  return item;
}

function chunks<T>(items: T[], size: number): T[][] {
  const result: T[][] = [];
  for (let start = 0; start < items.length; start += size) {
    result.push(items.slice(start, start + size));
  }
  return result;
}

/** Documents per upsert or update: at most 96 on an index that embeds a field. */
function batch(layout: Layout, size: number): number {
  return Math.min(size, layout.max_batch ?? size);
}

function unique<T>(items: T[]): T[] {
  return [...new Set(items)];
}

// ---------------------------------------------------------------- indexes

function camel(config: unknown): unknown {
  if (Array.isArray(config)) {
    return config.map(camel);
  }
  if (config !== null && typeof config === "object") {
    return Object.fromEntries(
      Object.entries(config).map(([key, entry]) => [key.replace(/_([a-z])/g, (_, c: string) => c.toUpperCase()), camel(entry)]),
    );
  }
  return config;
}

function indexTimeout(): number {
  return seconds("VECDSL_PINECONE_INDEX_TIMEOUT", 300);
}

export async function hasCollection(client: Client, args: { name: string }): Promise<boolean> {
  try {
    await client.pinecone.indexes.describe(args.name);
    return true;
  } catch (error) {
    if (error instanceof Errors.PineconeNotFoundError) {
      return false;
    }
    throw error;
  }
}

/** Deletes the index and, unless VECDSL_PINECONE_INDEX_TIMEOUT is 0, waits until it is gone. */
export async function dropCollection(client: Client, args: { name: string }): Promise<null> {
  client.forget(args.name);
  try {
    await client.pinecone.indexes.delete(args.name);
  } catch (error) {
    if (error instanceof Errors.PineconeNotFoundError) {
      return null;
    }
    throw error;
  }
  const limit = indexTimeout();
  const deadline = Date.now() + limit * 1000;
  while (limit > 0 && (await hasCollection(client, args))) {
    if (Date.now() > deadline) {
      throw new Error(`index ${args.name} still exists after ${limit} s`);
    }
    await new Promise((resolve) => setTimeout(resolve, 1000));
  }
  return null;
}

export async function createCollection(
  client: Client,
  args: { name: string; fields: Args; deployment?: Args; deletion_protection?: "enabled" | "disabled"; tags?: Record<string, string> },
): Promise<null> {
  const limit = indexTimeout();
  await client.pinecone.indexes.create({
    name: args.name,
    schema: { fields: camel(args.fields) as any },
    deployment: camel({
      deployment_type: "managed",
      cloud: process.env.VECDSL_PINECONE_CLOUD ?? DEFAULT_CLOUD,
      region: process.env.VECDSL_PINECONE_REGION ?? DEFAULT_REGION,
      ...args.deployment,
    }) as any,
    deletionProtection: args.deletion_protection,
    ...(args.tags === undefined || Object.keys(args.tags).length === 0 ? {} : { tags: args.tags }),
    waitUntilReady: limit > 0,
    timeout: limit > 0 ? limit * 1000 : undefined,
  });
  return null;
}

function describeIndex(client: Client, name: string): Promise<any> {
  return control(client, "GET", `/indexes/${segment(name)}`);
}

export async function requireCollection(client: Client, args: { name: string }): Promise<null> {
  if (!(await hasCollection(client, args))) {
    throw new Error(`index ${args.name} does not exist`);
  }
  return null;
}

async function ready(client: Client, name: string): Promise<boolean> {
  return Boolean((await describeIndex(client, name)).status?.ready);
}

/** configure_index: tags (replace_tags clears the tags not given, which Pinecone removes when set to "") and deletion protection. */
export async function configureCollection(
  client: Client,
  args: { name: string; tags?: Record<string, string>; replace_tags?: boolean; deletion_protection?: string },
): Promise<null> {
  const body: Args = {};
  if (args.tags !== undefined) {
    const current: Record<string, string> = args.replace_tags ? ((await describeIndex(client, args.name)).tags ?? {}) : {};
    const cleared = Object.fromEntries(Object.keys(current).filter((key) => !(key in args.tags!)).map((key) => [key, ""]));
    body.tags = { ...cleared, ...args.tags };
  }
  if (args.deletion_protection !== undefined) {
    body.deletion_protection = args.deletion_protection;
  }
  await control(client, "PATCH", `/indexes/${segment(args.name)}`, body);
  await poll(() => ready(client, args.name), `index ${args.name} is not ready`, indexTimeout());
  return null;
}

export async function hasNamespace(client: Client, args: { name: string; namespace: string }): Promise<boolean> {
  try {
    await data(client, args.name, "GET", `/namespaces/${segment(args.namespace)}`);
    return true;
  } catch (error) {
    if (error instanceof PineconeError && error.status === 404) {
      return false;
    }
    throw error;
  }
}

export async function createNamespace(client: Client, args: { name: string; namespace: string }): Promise<null> {
  await data(client, args.name, "POST", "/namespaces", { name: args.namespace });
  return null;
}

/** Deletes a namespace with its documents and waits until it is gone. */
export async function dropNamespace(client: Client, args: { name: string; namespace: string }): Promise<null> {
  await data(client, args.name, "DELETE", `/namespaces/${segment(args.namespace)}`);
  await poll(async () => !(await hasNamespace(client, args)), `namespace ${args.namespace} of ${args.name} still exists`, indexTimeout());
  return null;
}

/** A hosted embedding or reranking model (GET /models/{model}); unknown models fail with 404. */
export async function requireModel(client: Client, args: { model: string }): Promise<null> {
  await control(client, "GET", `/models/${segment(args.model)}`);
  return null;
}

function schedules(client: Client, name: string): Promise<any[]> {
  return paged((token) => control(client, "GET", `/indexes/${segment(name)}/backup-schedules` + query({ paginationToken: token })), "data");
}

export async function hasBackupSchedule(client: Client, args: { name: string; schedule: string }): Promise<boolean> {
  return (await schedules(client, args.name)).some((item) => item.name === args.schedule);
}

export async function createBackupSchedule(
  client: Client,
  args: { name: string; schedule: string; frequency: string; expire_after_days: number },
): Promise<null> {
  await control(client, "POST", `/indexes/${segment(args.name)}/backup-schedules`, {
    name: args.schedule,
    schedule: { type: "time-based", frequency: args.frequency },
    retention: { expire_after_days: Math.trunc(args.expire_after_days) },
  });
  return null;
}

export async function dropBackupSchedule(client: Client, args: { name: string; schedule: string }): Promise<null> {
  const found = (await schedules(client, args.name)).filter((item) => item.name === args.schedule);
  if (found.length === 0) {
    throw new Error(`backup schedule ${args.schedule} of ${args.name} does not exist`);
  }
  for (const item of found) {
    await control(client, "DELETE", `/backup-schedules/${segment(item.schedule_id)}`);
  }
  return null;
}

// ---------------------------------------------------------------- writes

function check(layout: Layout, record: Args): void {
  for (const [field, limit] of Object.entries(layout.limits ?? {})) {
    const item = record[field];
    if (item === null || item === undefined) {
      continue;
    }
    if (limit.dim !== undefined && item.length !== limit.dim) {
      throw new RangeError(`${field} has ${item.length} dimensions; ${layout.name} declares ${limit.dim}`);
    }
    if (limit.max_items !== undefined && item.length > limit.max_items) {
      throw new RangeError(`${field} has ${item.length} items; at most ${limit.max_items} are allowed`);
    }
    if (limit.max_length !== undefined) {
      for (const text of Array.isArray(item) ? item : [item]) {
        if (typeof text === "string" && text.length > limit.max_length) {
          throw new RangeError(`${field} is longer than ${limit.max_length} characters`);
        }
      }
    }
  }
}

/** Document fields of a record; Pinecone stores no nulls, so absent and null are the same. */
function fields(layout: Layout, record: Args): Args {
  check(layout, record);
  return Object.fromEntries(Object.entries(record).filter(([, item]) => item !== null && item !== undefined));
}

function documentOf(layout: Layout, row: Args): Args & { _id: string } {
  const record = { ...layout.defaults, ...row };
  const key = record[layout.key];
  if (key === null || key === undefined) {
    throw new Error(`record without primary key ${layout.key}: ${JSON.stringify(row)}`);
  }
  return { _id: documentId(key), ...fields(layout, record) };
}

function latest(positions: (number | undefined)[]): number | undefined {
  const known = positions.filter((item): item is number => item !== undefined);
  return known.length === 0 ? undefined : Math.max(...known);
}

/**
 * Waits until searches see a write (the index's reconciled log position reaches the write's) and then until
 * filtered fetches see it too.
 */
async function awaitWrite(client: Client, layout: Layout, target: number | undefined, written: Args[] = [], deleted: string[] = []): Promise<void> {
  const deadline = Date.now() + seconds("VECDSL_PINECONE_WAIT_SECONDS", 60) * 1000;
  if (target !== undefined && layout.probe !== undefined) {
    await awaitPosition(client, layout, target, deadline);
  }
  await settle(client, layout, written, deleted, deadline);
}

async function awaitPosition(client: Client, layout: Layout, target: number, deadline: number): Promise<void> {
  const probe = layout.probe!;
  const clause: Args = { type: probe.type, field: probe.field };
  if (probe.type === "dense_vector") {
    clause.values = [1, ...new Array<number>(Number(probe.dim) - 1).fill(0)];
  } else {
    clause.query = "vecdsl";
  }
  for (;;) {
    await client.documents(layout).search({ topK: 1, scoreBy: [clause as any] });
    if (client.reconciled !== undefined && client.reconciled >= target) {
      return;
    }
    if (Date.now() > deadline) {
      throw new Error(`${layout.name} did not reach log position ${target}`);
    }
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
}

/** Names of the fields an index declares (vectors and full-text text); every other field is metadata. */
async function schemaFields(client: Client, name: string): Promise<Set<string>> {
  let found = client.schemas.get(name);
  if (found === undefined) {
    found = new Set(Object.keys((await describeIndex(client, name)).schema?.fields ?? {}));
    client.schemas.set(name, found);
  }
  return found;
}

/** A filter that matches a written document only once filtering sees its metadata as written. */
function condition(layout: Layout, declared: Set<string>, document: Args): Filter {
  const parts: Filter[] = [{ [layout.key]: { $eq: keyOf(layout, document._id) } }];
  for (const [name, value] of Object.entries(document)) {
    if (name.startsWith("_") || name === layout.key || declared.has(name)) {
      continue;
    }
    if (typeof value === "boolean" || typeof value === "number" || typeof value === "string") {
      parts.push({ [name]: { $eq: value } });
    }
  }
  for (const name of (document._remove_fields ?? []) as string[]) {
    if (!declared.has(name)) {
      parts.push({ [name]: { $exists: false } });
    }
  }
  return parts.length === 1 ? parts[0] : { $and: parts };
}

/**
 * Filtered fetches see writes seconds after searches and report no log position, so the written documents are
 * fetched by filter until all match as written and none of the deleted ones is found.
 */
async function settle(client: Client, layout: Layout, written: Args[], deleted: string[], deadline: number): Promise<void> {
  if (written.length === 0 && deleted.length === 0) {
    return;
  }
  const declared = await schemaFields(client, layout.name);
  const latestById = new Map(written.map((document) => [document._id as string, document] as [string, Args]));
  let checks: [Filter, number][] = [];
  for (const chunk of chunks([...latestById.values()], SETTLE)) {
    const conditions = chunk.map((document) => condition(layout, declared, document));
    checks.push([conditions.length === 1 ? conditions[0] : { $or: conditions }, chunk.length]);
  }
  for (const chunk of chunks(unique(deleted), SETTLE)) {
    checks.push([{ [layout.key]: { $in: chunk.map((id) => keyOf(layout, id)) } }, 0]);
  }
  for (;;) {
    const open: [Filter, number][] = [];
    for (const check of checks) {
      if ((await matching(client, layout, check[0])).length !== check[1]) {
        open.push(check);
      }
    }
    checks = open;
    if (checks.length === 0) {
      return;
    }
    if (Date.now() > deadline) {
      throw new Error(`filtered reads of ${layout.name} do not see the last write yet`);
    }
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
}

async function existing(client: Client, layout: Layout, ids: string[]): Promise<Set<string>> {
  const found = new Set<string>();
  for (const chunk of chunks(ids, PAGE)) {
    const response = await client.documents(layout).fetch({ ids: chunk, includeFields: [layout.key] });
    Object.keys(response.documents).forEach((id) => found.add(id));
  }
  return found;
}

/** Ids of every document that matches a filter, through paginated fetches. */
async function matching(client: Client, layout: Layout, filter: Filter): Promise<string[]> {
  const found = new Set<string>();
  let token: string | undefined;
  for (;;) {
    const response = await client.documents(layout).fetch({
      filter,
      includeFields: [layout.key],
      limit: PAGE,
      ...(token === undefined ? {} : { paginationToken: token }),
    });
    Object.keys(response.documents).forEach((id) => found.add(id));
    const following = response.pagination?.next;
    if (!following || following === token) {
      return [...found];
    }
    token = following;
  }
}

async function allIds(client: Client, layout: Layout): Promise<string[]> {
  const found: string[] = [];
  const seen = new Set<string>();
  let token: string | undefined;
  for (;;) {
    const response = await client.documents(layout).list({ limit: LIST_PAGE, ...(token === undefined ? {} : { paginationToken: token }) });
    found.push(...response.documents.map((item) => item._id));
    token = response.pagination?.next;
    if (!token || seen.has(token)) {
      return found;
    }
    seen.add(token);
  }
}

async function targets(client: Client, layout: Layout, ids: unknown[] | undefined, filter: Filter | undefined): Promise<string[]> {
  if (ids !== undefined && ids.length > 0) {
    const wanted = unique(ids.map(documentId));
    const present = await existing(client, layout, wanted);
    let selected = wanted.filter((id) => present.has(id));
    if (filter !== undefined) {
      const matched = new Set(await matching(client, layout, filter));
      selected = selected.filter((id) => matched.has(id));
    }
    return selected;
  }
  if (filter !== undefined) {
    return matching(client, layout, filter);
  }
  throw new Error("the statement selects no records");
}

async function upsert(client: Client, layout: Layout, documents: Args[], batchSize: number): Promise<number | undefined> {
  const positions: (number | undefined)[] = [];
  for (const chunk of chunks(documents, batch(layout, batchSize))) {
    await client.documents(layout).upsert({ documents: chunk as any });
    positions.push(client.committed);
  }
  return latest(positions);
}

export async function insertRows(
  client: Client,
  args: { collection: Layout; rows: Args[]; on_conflict?: string; batch_size?: number; wait?: boolean },
): Promise<Args> {
  const documents = args.rows.map((row) => documentOf(args.collection, row));
  const present = await existing(client, args.collection, documents.map((document) => document._id));
  if (present.size > 0 && (args.on_conflict ?? "error") === "error") {
    throw new Error(`${present.size} records already exist in ${args.collection.name}`);
  }
  const fresh = documents.filter((document) => !present.has(document._id));
  const committed = await upsert(client, args.collection, fresh, args.batch_size ?? BATCH);
  if (args.wait) {
    await awaitWrite(client, args.collection, committed, fresh);
  }
  return { insert_count: fresh.length, skipped: documents.length - fresh.length };
}

export async function upsertRows(
  client: Client,
  args: { collection: Layout; rows: Args[]; batch_size?: number; wait?: boolean },
): Promise<Args> {
  const documents = args.rows.map((row) => documentOf(args.collection, row));
  const committed = await upsert(client, args.collection, documents, args.batch_size ?? BATCH);
  if (args.wait) {
    await awaitWrite(client, args.collection, committed, documents);
  }
  return { upsert_count: documents.length };
}

export async function updateRows(
  client: Client,
  args: {
    collection: Layout;
    ids?: unknown[];
    filter?: Filter;
    values?: Args;
    rows?: Args[];
    remove?: string[];
    mode?: string;
    append?: string[];
    remove_items?: string[];
    wait?: boolean;
  },
): Promise<Args> {
  const layout = args.collection;
  const replacements = new Map((args.rows ?? []).map((row) => [documentId(row[layout.key]), row] as [string, Args]));
  let selected: string[];
  if ((args.ids !== undefined && args.ids.length > 0) || args.filter !== undefined) {
    selected = await targets(client, layout, args.ids, args.filter);
  } else if (replacements.size > 0) {
    const present = await existing(client, layout, [...replacements.keys()]);
    selected = [...replacements.keys()].filter((id) => present.has(id));
  } else {
    throw new Error("update requires ids, a filter or records");
  }
  const replace = args.mode === "replace";
  const append = args.append ?? [];
  const arrays = [...append, ...(args.remove_items ?? [])];
  const stored = arrays.length > 0 ? await fetchDocuments(client, layout, selected, arrays) : new Map<string, Args>();
  const patches = selected.map((id) => {
    const record: Args = { ...replacements.get(id), ...args.values };
    const dropped = [...(args.remove ?? [])];
    for (const name of arrays) {
      const current: unknown[] = [...(stored.get(id)?.[name] ?? [])];
      const given: unknown[] = [...(record[name] ?? [])];
      const items = append.includes(name) ? [...current, ...given] : current.filter((item) => !given.includes(item));
      if (items.length > 0) {
        record[name] = items;
      } else {
        delete record[name];
        dropped.push(name);
      }
    }
    const key = record[layout.key];
    if (key !== null && key !== undefined && documentId(key) !== id) {
      throw new Error(`update cannot change the primary key ${layout.key}`);
    }
    record[layout.key] = keyOf(layout, id);
    if (replace) {
      return documentOf(layout, record);
    }
    const patch: Args = { _id: id, ...fields(layout, record) };
    if (dropped.length > 0) {
      patch._remove_fields = unique(dropped);
    }
    return patch;
  });
  const positions: (number | undefined)[] = [];
  for (const chunk of chunks(patches, batch(layout, PAGE))) {
    if (replace) {
      await client.documents(layout).upsert({ documents: chunk as any });
    } else {
      await client.documents(layout).update({ documents: chunk as any });
    }
    positions.push(client.committed);
  }
  if (args.wait) {
    await awaitWrite(client, layout, latest(positions), patches);
  }
  return { update_count: selected.length };
}

export async function deleteRows(
  client: Client,
  args: { collection: Layout; ids?: unknown[]; filter?: Filter; delete_all?: boolean; limit?: number; wait?: boolean },
): Promise<Args> {
  const layout = args.collection;
  let selected: string[];
  const positions: (number | undefined)[] = [];
  if (args.limit !== undefined) {
    const all =
      args.delete_all && args.filter === undefined && (args.ids === undefined || args.ids.length === 0)
        ? await allIds(client, layout)
        : await targets(client, layout, args.ids, args.filter);
    selected = sortIds(layout, all).slice(0, args.limit);
    for (const chunk of chunks(selected, PAGE)) {
      await client.documents(layout).delete({ ids: chunk });
      positions.push(client.committed);
    }
  } else if (args.delete_all) {
    selected = await allIds(client, layout);
    if (selected.length > 0) {
      await client.documents(layout).delete({ deleteAll: true });
      positions.push(client.committed);
    }
  } else {
    selected = await targets(client, layout, args.ids, args.filter);
    for (const chunk of chunks(selected, PAGE)) {
      await client.documents(layout).delete({ ids: chunk });
      positions.push(client.committed);
    }
  }
  if (args.wait) {
    await awaitWrite(client, layout, latest(positions), [], selected);
  }
  return { delete_count: selected.length };
}

/** Moves a metadata value to a new key in every document that has it: Pinecone renames no metadata keys. */
export async function renameField(
  client: Client,
  args: { collection: Layout; field: string; new_name: string; wait?: boolean },
): Promise<Args> {
  const layout = args.collection;
  const selected = await matching(client, layout, { [args.field]: { $exists: true } });
  const stored = await fetchDocuments(client, layout, selected, [args.field]);
  const patches = selected
    .filter((id) => stored.get(id)?.[args.field] !== undefined && stored.get(id)?.[args.field] !== null)
    .map((id) => ({ _id: id, [args.new_name]: stored.get(id)![args.field], _remove_fields: [args.field] }));
  const positions: (number | undefined)[] = [];
  for (const chunk of chunks(patches, batch(layout, PAGE))) {
    await client.documents(layout).update({ documents: chunk as any });
    positions.push(client.committed);
  }
  if (args.wait) {
    await awaitWrite(client, layout, latest(positions), patches);
  }
  return { update_count: patches.length };
}

/** Records of a local JSON array or JSON Lines file (file:// URI or path). */
export async function readRecords(client: Client, args: { location: string }): Promise<Args[]> {
  const { readFile } = await import("node:fs/promises");
  const path = args.location.startsWith("file://") ? args.location.slice("file://".length) : args.location;
  const text = await readFile(path, "utf-8");
  if (text.trimStart().startsWith("[")) {
    return JSON.parse(text) as Args[];
  }
  return text
    .split(/\r?\n/)
    .filter((line) => line.trim() !== "")
    .map((line) => JSON.parse(line) as Args);
}

/** A local file written as an insert (on-conflict error, ignore) or an upsert (update, replace). */
export async function importFile(
  client: Client,
  args: { collection: Layout; location: string; on_conflict?: string; batch_size?: number; wait?: boolean },
): Promise<Args> {
  const rows = await readRecords(client, { location: args.location });
  if (args.on_conflict === "update" || args.on_conflict === "replace") {
    return upsertRows(client, { collection: args.collection, rows, batch_size: args.batch_size, wait: args.wait });
  }
  return insertRows(client, {
    collection: args.collection,
    rows,
    on_conflict: args.on_conflict ?? "error",
    batch_size: args.batch_size,
    wait: args.wait,
  });
}

/** Bulk import of JSON Lines documents from object storage (paid plans); unless in the background, waits until it ends. */
export async function startImport(client: Client, args: { collection: Layout; uri: string; background?: boolean }): Promise<Args> {
  const name = args.collection.name;
  const started = await data(client, name, "POST", "/bulk/imports", { uri: args.uri, errorMode: { onError: "abort" } });
  const job: string = started.id;
  const status = (): Promise<any> => data(client, name, "GET", `/bulk/imports/${segment(job)}`);
  if (!args.background) {
    await poll(
      async () => ["Completed", "Failed", "Cancelled"].includes((await status()).status),
      `import ${job} has not finished`,
      seconds("VECDSL_PINECONE_IMPORT_TIMEOUT", 3600),
    );
  }
  const final = await status();
  if (final.status === "Failed" || final.status === "Cancelled") {
    throw new Error(`import ${job} ended ${final.status}: ${final.error}`);
  }
  return { import: job, status: final.status, records: final.recordsImported ?? null };
}

// ---------------------------------------------------------------- reads

function included(layout: Layout, output: string[], vectors?: string[]): string[] {
  return unique([layout.key, ...output, ...(vectors ?? [])]);
}

function rowOf(layout: Layout, id: string, document: Args, output: string[], vectors?: string[]): Args {
  const row: Args = { [layout.key]: keyOf(layout, id) };
  for (const name of [...output, ...(vectors ?? [])]) {
    row[name] = value(document[name] ?? null);
  }
  return row;
}

async function fetchDocuments(client: Client, layout: Layout, ids: string[], names: string[]): Promise<Map<string, Args>> {
  const found = new Map<string, Args>();
  for (const chunk of chunks(ids, PAGE)) {
    const response = await client.documents(layout).fetch({ ids: chunk, includeFields: names });
    Object.entries(response.documents).forEach(([id, document]) => found.set(id, document));
  }
  return found;
}

export async function getRows(
  client: Client,
  args: { collection: Layout; ids: unknown[]; output: string[]; vectors?: string[] },
): Promise<Args[]> {
  const layout = args.collection;
  const ids = unique(args.ids.map(documentId));
  const found = await fetchDocuments(client, layout, ids, included(layout, args.output, args.vectors));
  return ids.filter((id) => found.has(id)).map((id) => rowOf(layout, id, found.get(id)!, args.output, args.vectors));
}

export async function count(client: Client, args: { collection: Layout; filter?: Filter }): Promise<number> {
  return args.filter === undefined
    ? (await allIds(client, args.collection)).length
    : (await matching(client, args.collection, args.filter)).length;
}

/** Records in primary-key order; Pinecone pages by token without a stable order, so the runtime sorts. */
function compareValues(a: any, b: any): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

/** Stable sorts from the last sort key to the first; documents without a value come last for every key. */
function sortedBy(ids: string[], stored: Map<string, Args>, order: { key: string; direction?: string }[]): string[] {
  let result = ids;
  for (const clause of [...order].reverse()) {
    const has = (id: string): boolean => stored.get(id)?.[clause.key] !== undefined && stored.get(id)?.[clause.key] !== null;
    const sign = clause.direction === "desc" ? -1 : 1;
    const present = result.filter(has).sort((a, b) => sign * compareValues(stored.get(a)![clause.key], stored.get(b)![clause.key]));
    result = [...present, ...result.filter((id) => !has(id))];
  }
  return result;
}

export async function scroll(
  client: Client,
  args: {
    collection: Layout;
    output: string[];
    filter?: Filter;
    limit?: number;
    offset?: number;
    vectors?: string[];
    order?: { key: string; direction?: string }[];
  },
): Promise<Args[]> {
  const layout = args.collection;
  const all = args.filter === undefined ? await allIds(client, layout) : await matching(client, layout, args.filter);
  let ordered = sortIds(layout, all);
  if (args.order !== undefined && args.order.length > 0) {
    const keys = args.order.map((clause) => clause.key);
    ordered = sortedBy(ordered, await fetchDocuments(client, layout, ordered, keys), args.order);
  }
  const sorted = ordered.slice(args.offset ?? 0);
  const ids = args.limit === undefined ? sorted : sorted.slice(0, args.limit);
  const found = await fetchDocuments(client, layout, ids, included(layout, args.output, args.vectors));
  return ids.filter((id) => found.has(id)).map((id) => rowOf(layout, id, found.get(id)!, args.output, args.vectors));
}

/** A stored or literal vector as Pinecone takes it: dense values, or the indices and values of a sparse vector. */
function vectorOf(item: unknown): Vector {
  if (Array.isArray(item)) {
    return item.map(Number);
  }
  const sparse = item as Sparse;
  return { indices: sparse.indices.map(Number), values: sparse.values.map(Number) };
}

function isVector(item: unknown): boolean {
  return Array.isArray(item) || (typeof item === "object" && item !== null && "indices" in item);
}

/**
 * The scoring clause of a vector search: dense_vector, sparse_vector, or embed and sparse_embed with the query text
 * of a field Pinecone embeds. The SDK sends sparseValues as sparse_values.
 */
function vectorClause(field: string, vector: unknown, embed?: string): Args {
  if (embed !== undefined) {
    return { type: embed, field, query: vector };
  }
  const values = vectorOf(vector);
  return Array.isArray(values) ? { type: "dense_vector", field, values } : { type: "sparse_vector", field, sparseValues: values };
}

/** Canonical similarity of a Pinecone score; euclidean scores are squared distances. */
function similarity(metric: string, score: number): number {
  return metric === "euclidean" ? -Math.sqrt(Math.max(score, 0)) : score;
}

async function search(client: Client, layout: Layout, clause: Args, topK: number, names: string[], filter?: Filter): Promise<Match[]> {
  const response = await client.documents(layout).search({
    topK,
    scoreBy: [clause as any],
    includeFields: names,
    ...(filter === undefined ? {} : { filter }),
  });
  return response.matches as Match[];
}

function hit(layout: Layout, match: Match, score: number, output: string[], vectors?: string[]): Args {
  const row = rowOf(layout, match._id, match, output, vectors);
  const id = row[layout.key];
  delete row[layout.key];
  return { id, score: value(score), ...row };
}

function within(score: number, min?: number, max?: number): boolean {
  return (min === undefined || score >= min) && (max === undefined || score <= max);
}

function page<T>(hits: T[], limit: number, offset?: number): T[] {
  return hits.slice(offset ?? 0, (offset ?? 0) + limit);
}

/** The fields a search returns, with the rank field of a rerank clause. */
function ranked(names: string[], rerank?: Rerank): string[] {
  return rerank === undefined ? names : unique([...names, rerank.field]);
}

/**
 * Hits in the order of Pinecone Inference rerank: the rank field of each hit scored against the query text; a
 * hit's score becomes the reranker's relevance.
 */
async function reranked(client: Client, rerank: Rerank | undefined, scored: { match: Match; hit: Args }[]): Promise<Args[]> {
  if (rerank === undefined || scored.length === 0) {
    return scored.map((entry) => entry.hit);
  }
  const field = rerank.field;
  const body: Args = {
    model: rerank.model,
    query: rerank.query,
    rank_fields: [field],
    return_documents: false,
    documents: scored.map((entry) => ({ id: entry.match._id, [field]: String(entry.match[field] ?? "") })),
  };
  if (rerank.top_n !== undefined) {
    body.top_n = Math.min(rerank.top_n, scored.length);
  }
  if (rerank.parameters !== undefined) {
    body.parameters = rerank.parameters;
  }
  const ranking: Args[] = (await control(client, "POST", "/rerank", body)).data;
  return ranking.map((item) => ({ ...scored[Number(item.index)].hit, score: value(Number(item.score)) }));
}

export async function vectorSearch(
  client: Client,
  args: {
    collection: Layout; field: string; vector: Vector | string; limit: number; metric: string; output: string[]; filter?: Filter;
    offset?: number; score_min?: number; score_max?: number; native?: boolean; vectors?: string[]; embed?: string; rerank?: Rerank;
  },
): Promise<Args[]> {
  const layout = args.collection;
  const clause = vectorClause(args.field, args.vector, args.embed);
  const matches = await search(client, layout, clause, args.limit + (args.offset ?? 0),
    ranked(included(layout, args.output, args.vectors), args.rerank), args.filter);
  const scored: { match: Match; hit: Args }[] = [];
  for (const match of matches) {
    const score = args.native ? Number(match._score) : similarity(args.metric, Number(match._score));
    if (within(score, args.score_min, args.score_max)) {
      scored.push({ match, hit: hit(layout, match, score, args.output, args.vectors) });
    }
  }
  return page(await reranked(client, args.rerank, scored), args.limit, args.offset);
}

/**
 * The terms of a query text, lowercased: runs of letters and decimal digits; every other character separates terms, since
 * Pinecone's query_string syntax documents no escape character.
 */
function terms(text: string): string[] {
  return text.toLowerCase().split(/[^\p{L}\p{Nd}]+/u).filter((term) => term.length > 0);
}

/**
 * The Pinecone query_string of a rewritten text query: one clause per field, joined by OR, a boosted field as
 * (field:(...))^w; phrase "..."~slop, phrase prefix "..."*, terms with a fuzzy suffix, a required + per term, a regular
 * expression /pattern/, or the query_string text itself. The words and, or and not are quoted, not read as operators.
 */
export function queryStringText(query: string, fields: string[], rewrite: Rewrite): string {
  let body: string;
  if (rewrite.type === "regexp") {
    if (query.includes("/")) {
      throw new Error(`the regular expression ${JSON.stringify(query)} contains '/', which Pinecone query_string cannot escape`);
    }
    body = `/${query}/`;
  } else if (rewrite.type === "query_string") {
    body = `(${query})`;
  } else {
    const words = terms(query);
    if (words.length === 0) {
      throw new Error(`the query ${JSON.stringify(query)} has no terms`);
    }
    if (rewrite.type === "phrase" || rewrite.type === "phrase_prefix") {
      if (rewrite.type === "phrase_prefix" && words.length < 2) {
        throw new Error(`a phrase prefix needs at least two terms on Pinecone: ${JSON.stringify(query)}`);
      }
      let suffix = rewrite.type === "phrase_prefix" ? "*" : "";
      if (rewrite.slop !== undefined) {
        suffix += `~${Math.trunc(rewrite.slop)}`;
      }
      body = `("${words.join(" ")}"${suffix})`;
    } else {
      const sign = rewrite.required ? "+" : "";
      const fuzzy = rewrite.fuzzy ?? "";
      body = `(${words.map((word) => sign + (OPERATORS.has(word) ? `"${word}"` : word + fuzzy)).join(" ")})`;
    }
  }
  const boosts = rewrite.boosts ?? {};
  return fields.map((field) => (field in boosts ? `(${field}:${body})^${boosts[field]}` : `${field}:${body}`)).join(" OR ");
}

function textClause(query: string, names: string[], queryString?: boolean, rewrite?: Rewrite): Args {
  if (rewrite !== undefined) {
    return { type: "query_string", query: queryStringText(query, names, rewrite) };
  }
  return queryString ? { type: "query_string", query } : { type: "text", fields: names, query };
}

export async function keywordSearch(
  client: Client,
  args: {
    collection: Layout; query: string; fields: string[]; limit: number; output: string[]; query_string?: boolean;
    filter?: Filter; offset?: number; score_min?: number; score_max?: number; vectors?: string[]; rewrite?: Rewrite; rerank?: Rerank;
  },
): Promise<Args[]> {
  const layout = args.collection;
  const matches = await search(client, layout, textClause(args.query, args.fields, args.query_string, args.rewrite),
    args.limit + (args.offset ?? 0), ranked(included(layout, args.output, args.vectors), args.rerank), args.filter);
  const scored = matches.filter((match) => within(Number(match._score), args.score_min, args.score_max))
    .map((match) => ({ match, hit: hit(layout, match, Number(match._score), args.output, args.vectors) }));
  return page(await reranked(client, args.rerank, scored), args.limit, args.offset);
}

async function legScores(client: Client, layout: Layout, leg: Args, topK: number, names: string[]): Promise<Scored[]> {
  if (leg.kind === "vector") {
    const clause = vectorClause(leg.field, leg.vector, leg.embed);
    const scored = (await search(client, layout, clause, topK, names, leg.filter))
      .map((match) => ({ match, score: similarity(leg.metric, Number(match._score)) }));
    return scored.filter((entry) => within(entry.score, leg.score_min, leg.score_max));
  }
  return (await search(client, layout, textClause(leg.query, leg.fields, leg.query_string, leg.rewrite), topK, names, leg.filter))
    .map((match) => ({ match, score: Number(match._score) }));
}

/** Contribution of one leg: 1/(k + rank), weight * similarity, or weight * min-max normalized score. */
function fused(fusion: string, k: number, weight: number, ranked: Scored[]): Map<string, number> {
  if (fusion === "rrf") {
    return new Map(ranked.map((entry, index) => [entry.match._id, 1 / (k + index + 1)]));
  }
  if (fusion === "weighted") {
    return new Map(ranked.map((entry) => [entry.match._id, weight * entry.score]));
  }
  const scores = ranked.map((entry) => entry.score);
  const low = scores.length === 0 ? 0 : Math.min(...scores);
  const high = scores.length === 0 ? 0 : Math.max(...scores);
  return new Map(ranked.map((entry) => [entry.match._id, weight * (high > low ? (entry.score - low) / (high - low) : 1)]));
}

/** Fuses the legs' searches in the runtime; a Pinecone search scores by one dense clause or text clauses. */
export async function hybridSearch(
  client: Client,
  args: {
    collection: Layout; legs: Args[]; limit: number; fusion: string; output: string[]; k?: number; offset?: number;
    score_min?: number; score_max?: number; vectors?: string[]; rerank?: Rerank;
  },
): Promise<Args[]> {
  const layout = args.collection;
  const names = ranked(included(layout, args.output, args.vectors), args.rerank);
  const totals = new Map<string, number>();
  const documents = new Map<string, Match>();
  for (const leg of args.legs) {
    const ranked = await legScores(client, layout, leg, Number(leg.limit ?? args.limit + (args.offset ?? 0)), names);
    ranked.forEach((entry) => {
      if (!documents.has(entry.match._id)) {
        documents.set(entry.match._id, entry.match);
      }
    });
    for (const [id, part] of fused(args.fusion, args.k ?? 60, Number(leg.weight ?? 1), ranked)) {
      totals.set(id, (totals.get(id) ?? 0) + part);
    }
  }
  const order = compareIds(layout);
  const ranking = [...totals.keys()].sort((a, b) => totals.get(b)! - totals.get(a)! || order(a, b));
  const scored = ranking.filter((id) => within(totals.get(id)!, args.score_min, args.score_max))
    .map((id) => ({ match: documents.get(id)!, hit: hit(layout, documents.get(id)!, totals.get(id)!, args.output, args.vectors) }));
  return page(await reranked(client, args.rerank, scored), args.limit, args.offset);
}

export async function lookupVector(client: Client, args: { collection: Layout; field: string; id: unknown }): Promise<Vector> {
  const id = documentId(args.id);
  const found = await fetchDocuments(client, args.collection, [id], [args.field]);
  const document = found.get(id);
  if (document === undefined) {
    throw new Error(`record ${JSON.stringify(args.id)} not found in ${args.collection.name}`);
  }
  return vectorOf(document[args.field]);
}

/** A query text embedded by Pinecone Inference embed: dense values, or the indices and values of a sparse model. */
export async function embedQuery(client: Client, args: { model: string; text: string; parameters: Args }): Promise<Vector> {
  const data: Args = (await control(client, "POST", "/embed", { model: args.model, parameters: args.parameters, inputs: [{ text: args.text }] })).data[0];
  if (data.vector_type === "sparse") {
    return { indices: (data.sparse_indices as unknown[]).map(Number), values: (data.sparse_values as unknown[]).map(Number) };
  }
  return (data.values as unknown[]).map(Number);
}

function sparseMean(vectors: Sparse[]): Map<number, number> {
  const total = new Map<number, number>();
  for (const vector of vectors) {
    vector.indices.forEach((index, position) => total.set(index, (total.get(index) ?? 0) + vector.values[position]));
  }
  return new Map([...total].map(([index, weight]) => [index, weight / vectors.length]));
}

/** The sparse form of 2p - n, in ascending index order without zero weights. */
function sparseCentroid(positive: Sparse[], negative: Sparse[]): Sparse {
  let centroid = sparseMean(positive);
  if (negative.length > 0) {
    const anti = sparseMean(negative);
    const indices = new Set([...centroid.keys(), ...anti.keys()]);
    centroid = new Map([...indices].map((index) => [index, 2 * (centroid.get(index) ?? 0) - (anti.get(index) ?? 0)]));
  }
  const indices = [...centroid.keys()].filter((index) => centroid.get(index) !== 0).sort((a, b) => a - b);
  return { indices, values: indices.map((index) => centroid.get(index)!) };
}

/** Centroid of the positive examples, moved away from the centroid of the negatives: 2p - n. */
export async function recommendVector(
  client: Client,
  args: { collection: Layout; field: string; positives: unknown[]; negatives?: unknown[] },
): Promise<Vector> {
  const negatives = args.negatives ?? [];
  const keys = [...args.positives, ...negatives].filter((item) => !isVector(item)).map(documentId);
  const found = keys.length === 0 ? new Map<string, Args>() : await fetchDocuments(client, args.collection, keys, [args.field]);
  const resolve = (items: unknown[]): Vector[] =>
    items.map((item) => {
      if (isVector(item)) {
        return vectorOf(item);
      }
      const document = found.get(documentId(item));
      if (document === undefined) {
        throw new Error(`record ${JSON.stringify(item)} not found in ${args.collection.name}`);
      }
      return vectorOf(document[args.field]);
    });
  const positive = resolve(args.positives);
  const negative = resolve(negatives);
  if (positive.length === 0) {
    throw new Error("recommend requires at least one positive example");
  }
  if (!Array.isArray(positive[0])) {
    return sparseCentroid(positive as Sparse[], negative as Sparse[]);
  }
  return denseCentroid(positive as number[][], negative as number[][]);
}

function denseCentroid(positive: number[][], negative: number[][]): number[] {
  const mean = (vectors: number[][]): number[] =>
    vectors[0].map((_, index) => vectors.reduce((sum, vector) => sum + vector[index], 0) / vectors.length);
  const centroid = mean(positive);
  if (negative.length === 0) {
    return centroid;
  }
  const anti = mean(negative);
  return centroid.map((item, index) => 2 * item - anti[index]);
}

function randomSample<T>(items: T[], size: number): T[] {
  const pool = [...items];
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  return pool.slice(0, Math.min(size, pool.length));
}

/** A random sample (or the first records in key order) of the matching records, returned in key order. */
export async function sampleRows(
  client: Client,
  args: { collection: Layout; size: number; output: string[]; first?: boolean; filter?: Filter },
): Promise<Args[]> {
  const layout = args.collection;
  const all = sortIds(layout, args.filter === undefined ? await allIds(client, layout) : await matching(client, layout, args.filter));
  const picked = args.first ? all.slice(0, args.size) : sortIds(layout, randomSample(all, args.size));
  const found = await fetchDocuments(client, layout, picked, included(layout, args.output));
  return picked.filter((id) => found.has(id)).map((id) => rowOf(layout, id, found.get(id)!, args.output));
}

/**
 * A random sample of the matching records, each paired with its nearest neighbours within the sample (as Qdrant's distance
 * matrix); a record without the vector has no pairs.
 */
export async function distanceMatrix(
  client: Client,
  args: { collection: Layout; field: string; metric: string; sample?: number; limit?: number; filter?: Filter },
): Promise<Args[]> {
  const layout = args.collection;
  const limit = args.limit ?? 3;
  const all = args.filter === undefined ? await allIds(client, layout) : await matching(client, layout, args.filter);
  const picked = randomSample(all, args.sample ?? 10);
  const stored = await fetchDocuments(client, layout, picked, [args.field]);
  const keys = picked.map((id) => keyOf(layout, id));
  const pairs: Args[] = [];
  for (const id of picked) {
    const vector = stored.get(id)?.[args.field];
    if (vector === undefined || vector === null) {
      continue;
    }
    const clause = vectorClause(args.field, vector);
    const matches = await search(client, layout, clause, Math.min(limit + 1, picked.length), [layout.key], { [layout.key]: { $in: keys } });
    for (const match of matches.filter((item) => item._id !== id).slice(0, limit)) {
      pairs.push({ a: keyOf(layout, id), b: keyOf(layout, match._id), score: value(similarity(args.metric, Number(match._score))) });
    }
  }
  const order = (x: unknown, y: unknown): number => compareValues(x, y);
  return pairs.sort((x, y) => order(x.a, y.a) || order(x.b, y.b));
}

// ---------------------------------------------------------------- operations

/** Name, schema field types, the dense field's dimension and metric, deletion protection and tags; stats and index progress on request. */
export async function describe(client: Client, args: { name: string; stats?: boolean; index_progress?: boolean }): Promise<Args> {
  const found = await describeIndex(client, args.name);
  const schemaFields: Record<string, Args> = found.schema?.fields ?? {};
  const names = Object.keys(schemaFields).sort();
  const result: Args = {
    name: found.name,
    fields: Object.fromEntries(names.map((key) => [key, schemaFields[key]?.type ?? null])),
    deletion_protection: found.deletion_protection ?? null,
    tags: Object.keys(found.tags ?? {}).sort(),
  };
  for (const config of Object.values(schemaFields)) {
    if (config?.type === "dense_vector") {
      result.dimension = config.dimension ?? null;
      result.metric = config.metric ?? null;
    }
  }
  if (args.stats) {
    const namespaces: Record<string, Args> = (await data(client, args.name, "POST", "/describe_index_stats", {}))?.namespaces ?? {};
    const counts = Object.fromEntries(Object.keys(namespaces).sort().map((key) => [key, Math.trunc(Number(namespaces[key]?.vectorCount ?? 0))]));
    result.count = Object.values(counts).reduce((sum, item) => sum + item, 0);
    result.namespaces = counts;
  }
  if (args.index_progress) {
    result.index_progress = found.status?.ready ? "ready" : String(found.status?.state ?? "").toLowerCase();
  }
  return result;
}

/** Waits until the index reports ready; Pinecone indexes every write itself, so readiness is the build state. */
export async function awaitIndex(client: Client, args: { name: string; timeout?: number }): Promise<string> {
  await poll(() => ready(client, args.name), `index ${args.name} is not ready`, args.timeout ?? indexTimeout());
  const found = await describeIndex(client, args.name);
  return found.status?.ready ? "ready" : String(found.status?.state ?? "").toLowerCase();
}

function names(items: string[], prefix?: string, limit?: number): string[] {
  const sorted = unique(items.filter((item) => prefix === undefined || item.startsWith(prefix))).sort(compareValues);
  return limit === undefined ? sorted : sorted.slice(0, limit);
}

function backups(client: Client, name?: string): Promise<any[]> {
  const path = name === undefined ? "/backups" : `/indexes/${segment(name)}/backups`;
  return paged((token) => control(client, "GET", path + query({ paginationToken: token })), "data");
}

/** Sorted names: the project's indexes, an index's namespaces, or the backups of an index or the project. */
export async function listObjects(client: Client, args: { kind: string; scope?: { name: string }; prefix?: string; limit?: number }): Promise<string[]> {
  let items: string[];
  if (args.kind === "collections") {
    items = ((await control(client, "GET", "/indexes"))?.indexes ?? []).map((index: Args) => index.name);
  } else if (args.kind === "namespaces") {
    const scope = args.scope!;
    items = (await paged((token) => data(client, scope.name, "GET", "/namespaces" + query({ limit: 100, paginationToken: token })), "namespaces")).map(
      (item) => item.name,
    );
  } else {
    items = (await backups(client, args.scope?.name)).filter((backup) => backup.name).map((backup) => backup.name);
  }
  return names(items, args.prefix, args.limit);
}

/** A backup of every namespace of the index (paid plans); waits until it is ready. */
export async function createBackup(client: Client, args: { name: string; backup: string; description?: string }): Promise<Args> {
  const body: Args = { name: args.backup };
  if (args.description !== undefined) {
    body.description = args.description;
  }
  const created = await control(client, "POST", `/indexes/${segment(args.name)}/backups`, body);
  const status = async (): Promise<string> => String((await control(client, "GET", `/backups/${segment(created.backup_id)}`)).status);
  await poll(async () => ["Ready", "InitializationFailed"].includes(await status()), `backup ${args.backup} is not ready`, indexTimeout());
  const final = await status();
  if (final === "InitializationFailed") {
    throw new Error(`backup ${args.backup} of ${args.name} failed`);
  }
  return { backup: args.backup, status: final };
}

async function readyBackup(client: Client, backup: string): Promise<Args> {
  const found = (await backups(client)).filter((item) => item.name === backup && item.status === "Ready");
  if (found.length === 0) {
    throw new Error(`no ready backup named ${backup}`);
  }
  return found.reduce((best, item) => (String(item.created_at ?? "") > String(best.created_at ?? "") ? item : best));
}

/** Replaces the index with one created from the newest ready backup of that name (paid plans). */
export async function restoreBackup(client: Client, args: { name: string; backup: string; background?: boolean }): Promise<Args> {
  const source = await readyBackup(client, args.backup);
  if (await hasCollection(client, { name: args.name })) {
    await dropCollection(client, { name: args.name });
  }
  const job: string = (await control(client, "POST", `/backups/${segment(source.backup_id)}/create-index`, { name: args.name })).restore_job_id;
  const status = async (): Promise<string> => String((await control(client, "GET", `/restore-jobs/${segment(job)}`)).status);
  if (!args.background) {
    await poll(async () => ["Completed", "Failed", "Cancelled"].includes(await status()), `restore of ${args.name} has not finished`, indexTimeout());
    await poll(() => ready(client, args.name), `index ${args.name} is not ready`, indexTimeout());
  }
  const final = await status();
  if (final === "Failed" || final === "Cancelled") {
    throw new Error(`restore of ${args.name} from ${args.backup} ended ${final}`);
  }
  return { restored: args.name, status: final };
}

export async function dropBackup(client: Client, args: { backup: string }): Promise<Args> {
  const found = (await backups(client)).filter((item) => item.name === args.backup);
  if (found.length === 0) {
    throw new Error(`no backup named ${args.backup}`);
  }
  for (const item of found) {
    await control(client, "DELETE", `/backups/${segment(item.backup_id)}`);
  }
  return { deleted: found.length };
}

const SCHEMA_KEYS: Record<string, string[]> = {
  dense_vector: ["type", "dimension", "metric", "description"],
  sparse_vector: ["type", "description"],
  string: ["type", "description", "full_text_search", "embed", "sparse_embed", "store_text"],
};
const TEXT_KEYS = ["language", "stemming", "stop_words", "ngram"];

/** The schema of a described index in the form create accepts: server-set keys (lowercase, max_term_len) removed. */
function createSchema(described: Record<string, Args>): Args {
  const result: Args = {};
  for (const name of Object.keys(described).sort()) {
    const config = described[name] ?? {};
    const keys = SCHEMA_KEYS[config.type];
    if (keys === undefined) {
      continue;
    }
    const entry: Args = Object.fromEntries(keys.filter((key) => config[key] !== undefined && config[key] !== null).map((key) => [key, config[key]]));
    if (entry.full_text_search !== undefined) {
      entry.full_text_search = Object.fromEntries(
        Object.entries(entry.full_text_search as Args).filter(([key, item]) => TEXT_KEYS.includes(key) && item !== null && item !== undefined),
      );
    }
    result[name] = entry;
  }
  return result;
}

async function listIds(client: Client, name: string, namespace: string): Promise<string[]> {
  const path = `/namespaces/${segment(namespace)}/documents/list`;
  return (
    await paged((token) => data(client, name, "POST", path, { limit: LIST_PAGE, ...(token === undefined ? {} : { pagination_token: token }) }), "documents")
  ).map((item) => item._id as string);
}

/** A new index with the source's schema, deployment and tags, filled with a copy of every namespace. */
export async function cloneCollection(client: Client, args: { collection: Layout; target: string; deployment?: Args }): Promise<Args> {
  const sourceName = args.collection.name;
  const source = await describeIndex(client, sourceName);
  const placed = Object.fromEntries(Object.entries(source.deployment ?? {}).filter(([key]) => key === "cloud" || key === "region"));
  const tags = source.tags ?? undefined;
  await createCollectionRest(client, args.target, createSchema(source.schema?.fields ?? {}), { ...placed, ...args.deployment }, tags);
  const namespaces = unique([DEFAULT_NAMESPACE, ...(await listObjects(client, { kind: "namespaces", scope: { name: sourceName } }))]).sort(compareValues);
  const described: Args[] = Object.values(source.schema?.fields ?? {});
  const size = described.some((config) => config?.embed !== undefined || config?.sparse_embed !== undefined) ? EMBEDDED_BATCH : BATCH;
  let copied = 0;
  const positions = new Map<string, number | undefined>();
  const copies = new Map<string, Args[]>();
  for (const namespace of namespaces) {
    for (const chunk of chunks(await listIds(client, sourceName, namespace), size)) {
      const path = `/namespaces/${segment(namespace)}/documents/`;
      const documents: Record<string, Args> = (await data(client, sourceName, "POST", path + "fetch", { ids: chunk }))?.documents ?? {};
      const copy = chunk
        .filter((id) => documents[id] !== undefined)
        .map((id) => Object.fromEntries(Object.entries(documents[id]).filter(([key]) => key !== "_score")));
      if (copy.length > 0) {
        await data(client, args.target, "POST", path + "upsert", { documents: copy });
        positions.set(namespace, client.committed);
        copies.set(namespace, [...(copies.get(namespace) ?? []), ...copy]);
        copied += copy.length;
      }
    }
  }
  const probe = probeClause(createSchema(source.schema?.fields ?? {}));
  for (const [namespace, target] of positions) {
    await awaitRest(client, args.target, namespace, probe, target);
    const copyLayout: Layout = { name: args.target, namespace, key: args.collection.key, key_type: args.collection.key_type };
    await settle(client, copyLayout, copies.get(namespace) ?? [], [], Date.now() + seconds("VECDSL_PINECONE_WAIT_SECONDS", 60) * 1000);
  }
  return { copied };
}

/** A search clause that observes the log position of an index: its dense field, else a full-text field. */
function probeClause(schemaFields: Args): Args | undefined {
  for (const [name, config] of Object.entries(schemaFields)) {
    if (config.type === "dense_vector") {
      return { type: "dense_vector", field: name, values: [1, ...new Array<number>(Number(config.dimension) - 1).fill(0)] };
    }
  }
  for (const [name, config] of Object.entries(schemaFields)) {
    if (config.type === "string" && config.full_text_search !== undefined) {
      return { type: "text", field: name, query: "vecdsl" };
    }
  }
  return undefined;
}

/** The REST form of awaitPosition: searches until the reconciled log position reaches the write's. */
async function awaitRest(client: Client, name: string, namespace: string, probe: Args | undefined, target: number | undefined): Promise<void> {
  if (probe === undefined || target === undefined) {
    return;
  }
  const deadline = Date.now() + seconds("VECDSL_PINECONE_WAIT_SECONDS", 60) * 1000;
  for (;;) {
    await data(client, name, "POST", `/namespaces/${segment(namespace)}/documents/search`, { score_by: [probe], top_k: 1 });
    if (client.reconciled !== undefined && client.reconciled >= target) {
      return;
    }
    if (Date.now() > deadline) {
      throw new Error(`${name} did not reach log position ${target}`);
    }
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
}

/** create_index over REST with the schema as described (the SDK would camel-case nested keys). */
async function createCollectionRest(client: Client, name: string, schemaFields: Args, deployment: Args, tags?: Record<string, string>): Promise<void> {
  const body: Args = {
    name,
    schema: { fields: schemaFields },
    deployment: {
      deployment_type: "managed",
      cloud: process.env.VECDSL_PINECONE_CLOUD ?? DEFAULT_CLOUD,
      region: process.env.VECDSL_PINECONE_REGION ?? DEFAULT_REGION,
      ...deployment,
    },
  };
  if (tags !== undefined && Object.keys(tags).length > 0) {
    body.tags = tags;
  }
  await control(client, "POST", "/indexes", body);
  await poll(() => ready(client, name), `index ${name} is not ready`, indexTimeout());
}
